# Generated by build.py from recipe.yml for recipe http-multiplex-requests-over-http2. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site slow
printf '%s\n' 'file 1' > site/f1.txt
printf '%s\n' 'file 2' > site/f2.txt
printf '%s\n' 'file 3' > site/f3.txt
printf '%s\n' 'file 4' > site/f4.txt
printf '%s\n' 'file 5' > site/f5.txt
printf '%s\n' 'file m1' > site/m1.txt
printf '%s\n' 'file m2' > site/m2.txt
printf '%s\n' 'file m3' > site/m3.txt
printf '%s\n' 'file m4' > site/m4.txt
printf '%s\n' 'file m5' > site/m5.txt
printf '%s\n' 'file 1' > slow/f1.txt
printf '%s\n' 'file 2' > slow/f2.txt
printf '%s\n' 'file 3' > slow/f3.txt
printf '%s\n' 'file 4' > slow/f4.txt
printf '%s\n' 'file 5' > slow/f5.txt
cat > elapsed.sh <<'EOF'
# Runs the command given as arguments, then prints how many whole seconds it took.
start=$(date +%s)
"$@" || exit
echo "$(( $(date +%s) - start )) s"
EOF
surl --directory site --trace-ascii trace.txt http://127.0.0.1:8080/ &
sleep 1
curl --http2-prior-knowledge -Z -s -w "%{http_version}\n" -o "got/f#1.txt" --create-dirs "http://127.0.0.1:8080/f[1-5].txt"
kill $(jobs -p)
